parameters.functionCode:
const daysLimit = 30;
const now = new Date();

return items
  .map(i => i.json)
  .filter(p => {
    if (!p.last_activity_at) return false;
    const last = new Date(p.last_activity_at);
    const diffDays = (now - last) / (1000 * 60 * 60 * 24);
    return diffDays <= daysLimit;
  })
  .slice(0, 20) // limita número de proyectos por ejecución
  .map(p => ({ json: p }));

const allBranches = items.map(i => i.json);

const PRIORITY = ["main", "master", "develop", "staging", "production"];

const important = allBranches
  .filter(b => {
    const n = b.name;
    if (PRIORITY.includes(n)) return true;
    if (n.startsWith("feature/")) return true;
    return false;
  })
  .map(b => ({ json: { branch: b, project_id: $items("Filter Active Projects")[0].json.id } }));

return important.slice(0, 10);

const files = items.map(i => i.json);

const hasFile = (name) => files.some(f => f.path === name || f.name === name || f.path.endsWith(name));

let type = 'generic';

if (hasFile('pom.xml')) {
  if (hasFile('Dockerfile') && (hasFile('src/main/resources/application.yml') || hasFile('src/main/resources/application.yaml'))) {
    type = 'java-microservice';
  } else {
    type = 'java';
  }
} else if (hasFile('package.json')) {
  if (files.some(f => f.path.includes('angular.json'))) {
    type = 'angular';
  } else {
    type = 'react';
  }
} else if (hasFile('Dockerfile')) {
  type = 'docker';
}

return [{
  json: {
    project_id: $items("IF - Needs CI", 0, 0).json.project_id,
    branch: $items("IF - Needs CI", 0, 0).json.branch,
    project_type: type
  }
}];

const created = items.map(i => ({
  project_id: i.json.project_id,
  branch: i.json.branch.name || i.json.branch,
}));

return [{ json: { created } }];

